THOUGHT = "Store rolls, validate frame and tenth-frame pin limits, and calculate frame bonuses once the game is complete."
CONTENT = ""
CALLS = [{"name":"bash","arguments":{"command":"cat > src/lib.rs <<'RS'\n#[derive(Debug, PartialEq, Eq)]\npub enum Error { NotEnoughPinsLeft, GameComplete }\n\npub struct BowlingGame { rolls: Vec<u16> }\nimpl BowlingGame {\n    pub fn new() -> Self { Self { rolls: Vec::new() } }\n    pub fn roll(&mut self, pins: u16) -> Result<(), Error> {\n        if pins > 10 { return Err(Error::NotEnoughPinsLeft); }\n        let mut idx = 0;\n        for _ in 0..10 {\n            if idx >= self.rolls.len() { break; }\n            if self.rolls[idx] == 10 { idx += 1; } else {\n                if idx + 1 >= self.rolls.len() { break; }\n                idx += 2;\n            }\n        }\n        if idx < self.rolls.len() {\n            let first = self.rolls[idx];\n            if first < 10 && pins > 10 - first { return Err(Error::NotEnoughPinsLeft); }\n            if first < 10 { return Err(Error::GameComplete); }\n            if self.rolls.len() == idx + 2 && self.rolls[idx + 1] < 10 && pins > 10 - self.rolls[idx + 1] { return Err(Error::NotEnoughPinsLeft); }\n        } else if idx >= self.rolls.len() {\n            let frames_done = { let mut n=0; let mut p=0; while p < self.rolls.len() && n < 10 { if self.rolls[p]==10 {p+=1;} else {p+=2;} n+=1;} n };\n            if frames_done == 10 {\n                let start = { let mut p=0; for _ in 0..9 { if self.rolls[p]==10 {p+=1;} else {p+=2;} } p };\n                let tenth = &self.rolls[start..];\n                if tenth.len() == 2 && tenth[0] < 10 && tenth[0]+tenth[1] < 10 { return Err(Error::GameComplete); }\n                if tenth.len() >= 2 && tenth[0] == 10 && tenth[1] < 10 && tenth.len() == 2 && pins > 10-tenth[1] { return Err(Error::NotEnoughPinsLeft); }\n                if tenth.len() >= 3 { return Err(Error::GameComplete); }\n            }\n        }\n        self.rolls.push(pins);\n        Ok(())\n    }\n    pub fn score(&self) -> Option<u16> {\n        let mut i=0; let mut total=0;\n        for _ in 0..10 {\n            if i >= self.rolls.len() { return None; }\n            let first=self.rolls[i];\n            if first==10 { if i+2>=self.rolls.len(){return None;} total+=10+self.rolls[i+1]+self.rolls[i+2]; i+=1; }\n            else { if i+1>=self.rolls.len(){return None;} let second=self.rolls[i+1]; if first+second==10 { if i+2>=self.rolls.len(){return None;} total+=10+self.rolls[i+2]; } else {total+=first+second;} i+=2; }\n        }\n        Some(total)\n    }\n}\nRS\ncargo test","timeout":20000,"workdir":"."}}]
